from collections import deque
im=Image.open('/home/robot/captures/top_003.png').convert('L')
w,h=im.size
pix=im.load()
thr=120
# Binary mask as bytearray
mask=bytearray(w*h)
for y in range(h):
 for x in range(w):
  if pix[x,y]>thr:
