  area=len(xs)
  if area>50:
   comps.append((comp,area,min(xs),min(ys),max(xs),max(ys),sum(xs)/area,sum(ys)/area))
print('components',len(comps))
for c in sorted(comps,key=lambda t:-t[1])[:20]:
 print(c)
